  if (val instanceof HTTPResponse || (val as any)?.[kHTTPResponse] === true) {
    return val;
  }

  // JSON
  if (isJSONSerializable(val, valType)) {
    return {
      body: JSON.stringify(val, undefined, config.debug ? 2 : undefined),
      headers: jsonHeaders,
    };
