  readonly body: Record<string, unknown> | undefined;

  /**
   * RFC 9457 `type`: URI reference identifying the problem type. Defaults to `about:blank` in the JSON body.
   */
  readonly type: string | undefined;

  /**
   * RFC 9457 `instance`: URI reference identifying this occurrence of the problem.
   */
  readonly instance: string | undefined;

  /**
   * Flag to indicate that the error was not handled by the application.
   *
   * Unhandled error stack trace, data and message are hidden in non debug mode for security reasons.
   */
  readonly unhandled: boolean | undefined;

  /**
   * Check if the input is an instance of HTTPError using its constructor name and status.
   *
   * It is safer than using `instanceof` because it works across different contexts (e.g., if the error was thrown in a different module).
   *
   * Requiring a `status` rejects unrelated errors named `HTTPError` (e.g. from fetch clients like `ky` or `got`), while
   * still accepting HTTPError-shaped errors from other packages (e.g. srvx `BodyTooLargeError`).
   */
  static override isError(input: any): input is HTTPError {
    return (
      input instanceof Error && input?.name === "HTTPError" && (input as HTTPError).status > 99
    );
  }

  /**
   * Create a new HTTPError with the given status code and optional status text and details.
   *
   * @example
   *
   * HTTPError.status(404)
   * HTTPError.status(418, "I'm a teapot")
   * HTTPError.status(403, "Forbidden", { message: "Not authenticated" })
   */
  static status(
    status: number,
    statusText?: string,
    details?: Exclude<ErrorDetails, "status" | "statusText" | "statusCode" | "statusMessage">,
  ): HTTPError {
    return new HTTPError({ ...details, statusText, status });
  }

  /**
   * Create a new HTTPError with the given message and optional details.
   *
   * @example
   *
   * new HTTPError("This is an error", { status: 400, cause: error })
   * new HTTPError({ message: "This is an error", status: 500, statusText: "Not Found", data: {} })
   */
  constructor(message: string, details?: ErrorDetails);
  constructor(details: ErrorDetails);
  constructor(arg1: string | ErrorDetails, arg2?: ErrorDetails) {
    let messageInput: string | undefined;
    let details: ErrorDetails | undefined;
    if (typeof arg1 === "string") {
      messageInput = arg1;
      details = arg2;
    } else {
      details = arg1;
    }

    const status = sanitizeStatusCode(
      (details as ErrorBody)?.status ||
        (details as ErrorInput)?.statusCode ||
        (details?.cause as ErrorBody)?.status ||
        (details?.cause as ErrorInput)?.statusCode,
      500,
    );

    const statusText = sanitizeStatusMessage(
      (details as ErrorBody)?.statusText ||
        (details as ErrorInput)?.statusMessage ||
        (details?.cause as ErrorBody)?.statusText ||
        (details?.cause as ErrorInput)?.statusMessage,
    );

    const message: string =
      messageInput ||
      details?.message ||
      (details?.cause as ErrorDetails)?.message ||
      (details as ErrorBody)?.statusText ||
      (details as ErrorInput)?.statusMessage ||
      ["HTTPError", status, statusText].filter(Boolean).join(" ");

    // @ts-ignore https://v8.dev/features/error-cause
    super(message, { cause: details });
    this.cause = details;

    this.status = status;
    this.statusText = statusText || undefined;

    const rawHeaders = (details as ErrorInput)?.headers || (details?.cause as ErrorInput)?.headers;
    this.headers = rawHeaders ? new Headers(rawHeaders) : undefined;

    this.unhandled =
      (details as ErrorBody)?.unhandled ?? (details?.cause as ErrorBody)?.unhandled ?? undefined;

    this.data = (details as ErrorBody)?.data as DataT | undefined;
    this.body = (details as ErrorBody)?.body;

    // Not read from `cause`: wrapped foreign errors may carry an unrelated `type`
    const type = (details as ErrorBody)?.type;
    this.type = typeof type === "string" ? type : undefined;
    const instance = (details as ErrorBody)?.instance;
    this.instance = typeof instance === "string" ? instance : undefined;
  }

  /**
   * @deprecated Use `status`
   */
  get statusCode(): number {
    return this.status;
  }

  /**
   * @deprecated Use `statusText`
   */
  get statusMessage(): string | undefined {
    return this.statusText;
  }

  toJSON(): Omit<ErrorBody, "body"> & ErrorBody["body"] {
    const unhandled = this.unhandled;
    return {
      status: this.status,
      statusText: this.statusText,
      unhandled: unhandled,
      message: unhandled ? "HTTPError" : this.message,
      data: unhandled ? undefined : this.data,
      ...(unhandled ? undefined : this.body),
    };
  }
}

