const fs=require("fs");const f="src/utils/internal/status-text.ts";
const s=fs.readFileSync(f,"utf8");
const m=[...s.matchAll(/^  (\d+): "(.*)",$/gm)];
const packed=m.map(x=>x[1]+" "+x[2]).join("|");
const out=`// RFC 9110 reason phrases, packed as "<code> <phrase>|..." to keep the core bundle small
const PHRASES: Record<string, string> = /* @__PURE__ */ Object.fromEntries(
  "${packed}".split("|").map((p) => [p.slice(0, 3), p.slice(4)]),
);

/**
 * Default reason phrase for an HTTP status code (\`"Error"\` when unknown).
 */
export function getStatusPhrase(status: number): string {
  return PHRASES[status] || "Error";
}
`;
